    val stories = listOf(
        StorySeries(
            id = "the_saturday_repair_club",
            title = "The Saturday Repair Club",
            tagline = "A neighbourhood club discovers the value of sharing practical skills.",
            parts = listOf(
                StoryPart(1, "The Broken Radio", listOf("Zain brought an old radio that had belonged to his grandfather to the community centre's repair day. It no longer worked, but he hoped someone could help him understand its history.", "The volunteers explained that they could inspect objects, but safety came first. Electrical repairs would be referred to qualified technicians.", "A retired technician, Mrs Udo, checked the label and asked Zain to find the model information.")),
                StoryPart(2, "A Table of Tools", listOf("The centre had separate tables for textiles, bicycles, toys, and household objects. Each table had a volunteer who understood its limits.", "Zain watched someone mend a schoolbag strap while another volunteer taught a child to sew a button.", "Mrs Udo explained that useful repair work began by knowing what could safely be attempted.")),
                StoryPart(3, "The Missing Manual", listOf("The radio's model number led to a scanned manual in a public archive. It warned that internal repairs should be handled by trained technicians.", "Mrs Udo noticed that the power adapter did not match the model. She did not connect it and explained why an unsuitable adapter could damage equipment.", "Zain found an old receipt showing that the original adapter had been replaced years earlier.")),
                StoryPart(4, "A Story in the Receipt", listOf("The receipt came from an electronics shop that had closed. Its former owner, Mr Nkem, now volunteered at the centre's history desk.", "He remembered Zain's grandfather listening to football commentary with neighbours and later donating the radio to the youth room.", "Mr Nkem suggested preserving the radio's story even if it could not be restored.")),
                StoryPart(5, "The Repair Decision", listOf("A qualified repairer inspected the radio and explained that a safe restoration would cost more than the family expected. Some parts were no longer available.", "Zain felt disappointed. Mrs Udo suggested keeping it safely as a family keepsake and recording its story for the centre archive.", "Zain asked whether he could still help at repair day. The textile team needed assistance sorting donated fabric.")),
                StoryPart(6, "A Different Skill", listOf("Zain learned to identify strong fabric, match thread, and reinforce a torn bag strap. The volunteer let him practise on scrap material first.", "He discovered that repairing something did not always mean returning it to its original state. Sometimes a careful improvement made it useful in a new way.", "The repaired bag was added to the centre's free school-supplies shelf with the donor's permission.")),
                StoryPart(7, "The Neighbourhood List", listOf("The club kept receiving requests for work it could not safely perform. Volunteers created a directory of qualified local services and clear guidance about the club's limits.", "Zain helped make the directory easy to read, confirming contact details and encouraging people to request estimates before agreeing to work.", "The directory helped the club avoid promising more than its volunteers could deliver.")),
                StoryPart(8, "The Listening Corner", listOf("The history desk invited residents to record short memories about objects they had kept. Zain brought a photograph of his grandfather beside the radio.", "Several people recognised the same model and shared memories of listening to broadcasts together.", "Zain recorded his account and labelled it as a family memory rather than verified broadcast history.")),
                StoryPart(9, "Repair Day Returns", listOf("At the next event, Zain welcomed visitors and directed them to the right tables. The club had added safety notices and a referral process for specialist work.", "A child arrived with a torn kite. A volunteer helped mend its fabric and explained how to check its frame before use.", "The centre filled with conversation, careful work, and objects given another useful chapter.")),
                StoryPart(10, "What We Keep", listOf("Zain placed the radio's photograph and story in the archive. The radio stayed with his family, safely stored as a reminder of evenings shared with his grandfather.", "The repair club published its directory and invited skilled volunteers to join. It measured success by what people learned, not simply by the number of objects fixed.", "Zain left with a repaired schoolbag and a new appreciation: sometimes the most valuable repair was helping someone discover what they could do next."))
            )
